import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { PresentUserControllerComponent } from '../present-user-controller/present-user-controller.component';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { MatMenuModule } from '@angular/material/menu';
import { presentDetail, presentEvents, presentStatus, temaUsers } from '../../../interfaces/present.tool.interface';
import { PresentToolService } from '../../../services/present-tool/present-tool.service';
import { MatTooltipModule } from '@angular/material/tooltip';
import { Subscription } from 'rxjs';
import { SocketService } from '../../../../core/services/socket/socket.service';
import { toolEvents } from '../../../../pdf/interfaces/pdf.interface';
import { ScreenShareComponent } from '../../screenshare/screen-share/screen-share.component';
import { ScreenViewerComponent } from '../../screenshare/screen-viewer/screen-viewer.component';
import { DocumentTab } from '../../../../userpanel/interfaces/individual.interface';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { NgClass } from '@angular/common';

@Component({
  selector: 'present-tool',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [PresentUserControllerComponent, AvatarComponent, IconComponent, ButtonComponent, MatMenuModule, MatTooltipModule, ScreenShareComponent, ScreenViewerComponent, NgClass],
  templateUrl: './present-tool.component.html',
  styleUrl: './present-tool.component.scss'
})
export class PresentToolComponent implements OnInit {

  @Input() nPresentid: string;
  @Input() isHost: boolean;
  @Input() nIndexid: string;
  @Input() isPaused: boolean;
  @Output() isPausedChange = new EventEmitter<boolean>();
  @Output() presentEvents = new EventEmitter<toolEvents>();
  @Input() cStatus: presentStatus = 'I';
  @Output() cStatusChange = new EventEmitter<presentStatus>();
  @Input() documentList: DocumentTab[] = [];
  presentDetail: presentDetail = {} as presentDetail
  active_teams: temaUsers[] = [];
  global_teams: temaUsers[] = [];
  presentSubscribe: Subscription;
  presentPositionSubscribe: Subscription;
  presentTabSubscribe: Subscription;
  presentHighlightSubscribe: Subscription;
  presentationSubscribe: Subscription;

  presentCompareSubscribe: Subscription;
  presentCompareDataSubscribe: Subscription;
  @Input() isEndPresentation: boolean = false;
  @Output() isEndPresentationChange = new EventEmitter<boolean>();

  @Input() isScreenSharing: boolean = false;
  @Output() isScreenSharingChange = new EventEmitter<boolean>();
  isLoaded: boolean = false;
  isHaveRequest: boolean = false;
  hideControles: boolean = false;
  constructor(private presentToolService: PresentToolService, private cdr: ChangeDetectorRef, private socket: SocketService, private tost: TostbarService) {
    this.presentSubscribe = this.socket.getPresentationTools().subscribe((res: presentEvents) => {
      const data = res?.data;
      if (res.event == 'ASK-REQ') {
        const team = this.active_teams.find(a => a.users.find(b => b.nUserid == data.nAskby));
        if (team) {
          const usr = team.users.find(a => a.nUserid == data.nAskby);
          usr.cAStatus = 'RQ';
        }
        this.active_teams = [...this.active_teams];
        this.checkForReq()
        this.cdr.detectChanges();
      } else if (res.event == 'USER-COUNT-UPDATED') {
        if (res.data.nTotal) {
          this.presentDetail.totalusers = res.data.nTotal
          this.cdr.detectChanges();
        }

      }
    })

    this.presentPositionSubscribe = this.socket.getPresentationPosition().subscribe((data: any) => {
      if (this.isHost || this.isPaused) return;
      this.presentEvents.emit({ event: 'PRESENT-POSITION', data: data });
    })

    this.presentTabSubscribe = this.socket.getPresentationTab().subscribe((data: any) => {
      if (this.isHost || this.isPaused) return;
      this.presentEvents.emit({ event: 'PRESENT-TAB-CHANGE', data: data });
    })

    this.presentHighlightSubscribe = this.socket.getPresentHighlights().subscribe((e: any) => {
      if (this.isHost || this.isPaused) return;
      this.presentEvents.emit(e);
    })

    this.presentationSubscribe = this.socket.getPresentations().subscribe((res: presentEvents) => {
      const data = res?.data;
      if (res.event == 'USER-JOINED' || res.event == 'USER-LEFT') {
        const team = this.active_teams.find(a => a.users.find(b => b.nUserid == data.nUserid));
        if (team) {
          const usr = team.users.find(a => a.nUserid == data.nUserid);
          usr.isLive = (res.event == 'USER-JOINED');
        }
        this.active_teams = [...this.active_teams];

        this.cdr.detectChanges();
      }
    });


    this.presentCompareSubscribe = this.socket.getPresentCompare().subscribe((data: any) => {
      if (this.isHost || this.isPaused) return;
      this.presentEvents.emit({ event: 'PRESENT-COMPARE', data });
    })

    this.presentCompareDataSubscribe = this.socket.getPresentCompareData().subscribe((data: any) => {
      if (this.isHost || this.isPaused) return;
      this.presentEvents.emit({ event: 'PRESENT-COMPARE-DATA', data });
    })

    // Callout events
    this.socket.getPresentCallout().subscribe((data: any) => {
      if (this.isHost || this.isPaused) return;
      this.presentEvents.emit({ event: 'PRESENT-CALLOUT', data });
    });
    this.socket.getPresentCalloutDismiss().subscribe((data: any) => {
      if (this.isHost || this.isPaused) return;
      this.presentEvents.emit({ event: 'PRESENT-CALLOUT-DISMISS', data });
    });
    this.socket.getPresentCalloutHighlight().subscribe((data: any) => {
      if (this.isHost || this.isPaused) return;
      this.presentEvents.emit({ event: 'PRESENT-CALLOUT-HIGHLIGHT', data });
    });

  }



  async ngOnInit() {
    this.presentDetail = await this.presentToolService.getPresentInfo(this.nPresentid);
    this.cStatus = this.presentDetail.cStatus;
    this.cStatusChange.emit(this.cStatus)
    this.isLoaded = true;
    this.cdr.detectChanges();
  }



  async managePresentStatus(Status: 'L' | 'P' | 'C') {
    if (!this.documentList?.length) {
      this.tost.error('No document selected')
      return;
    }

    const res = await this.presentToolService.managePresentStatus(this.nPresentid, Status);
    if (res.msg == 1) {

      this.cStatus = Status;
      this.cStatusChange.emit(this.cStatus);
    } else {
      this.tost.error(res["value"])
    }
    this.cdr.detectChanges();
  }

  pausePresent() {
    this.isPaused = !this.isPaused;
    this.isPausedChange.emit(this.isPaused);
    if (!this.isPaused) {
      this.presentEvents.emit({ event: 'UNPAUSED', data: {} });
    } else {
      this.presentEvents.emit({ event: 'PAUSED', data: {} });
    }
    this.cdr.detectChanges();
  }


  ngOnDestroy(): void {
    try {
      if (this.presentSubscribe) {
        this.presentSubscribe.unsubscribe();
      }

      if (this.presentPositionSubscribe) {
        this.presentPositionSubscribe.unsubscribe();
      }

      if (this.presentTabSubscribe) {
        this.presentTabSubscribe.unsubscribe();
      }

      if (this.presentHighlightSubscribe) {
        this.presentHighlightSubscribe.unsubscribe();
      }

      if (this.presentationSubscribe) {
        this.presentHighlightSubscribe.unsubscribe();
      }

      if (this.presentCompareSubscribe) {
        this.presentCompareSubscribe.unsubscribe();
      }

      if (this.presentCompareDataSubscribe) {
        this.presentCompareDataSubscribe.unsubscribe();
      }
    } catch (error) {

    }
  }


  endPresentation() {
    this.isEndPresentation = true;
    this.isEndPresentationChange.emit(this.isEndPresentation);
    this.cdr.detectChanges();
  }


  StartScreenSharing(val) {
    this.isScreenSharing = val;
    this.isScreenSharingChange.emit(this.isScreenSharing);
    this.cdr.detectChanges();
  }


  OnUserControll(e: toolEvents) {
    if (e.event == 'USER-UPDATED') {
      this.ngOnInit();
    }
  }

  checkForReq() {
    this.isHaveRequest = false
    try {
      const team = this.active_teams.find(a => a.users.find(b => b.cAStatus == 'RQ'));
      this.isHaveRequest = team ? true : false;
    } catch (error) {

    }
    this.cdr.detectChanges();
  }



}
